const SKY_VERT = `
varying vec3 vWorldPos;
void main() {
  vec4 world = modelMatrix * vec4(position, 1.0);
  vWorldPos = world.xyz;
  gl_Position = projectionMatrix * viewMatrix * world;
}
`

const SKY_FRAG = `
varying vec3 vWorldPos;
uniform vec3 uTop;
uniform vec3 uMid;
uniform vec3 uHorizon;
uniform vec3 uSunDir;
void main() {
  vec3 dir = normalize(vWorldPos);
  float h = clamp(dir.y, 0.0, 1.0);
  vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.28, h));
  col = mix(col, uTop, smoothstep(0.25, 0.85, h));
  float sunDot = max(dot(dir, normalize(uSunDir)), 0.0);
  col += vec3(1.0, 0.72, 0.36) * pow(sunDot, 420.0) * 2.4;
  col += vec3(1.0, 0.62, 0.28) * pow(sunDot, 14.0) * 0.28;
  float band = smoothstep(0.92, 1.0, 1.0 - abs(h - 0.06));
  col += vec3(1.0, 0.7, 0.4) * band * 0.12;
  gl_FragColor = vec4(col, 1.0);
}
`

