  return {
    group,
    ring,
    icon,
    type: spec.type,
    name: spec.name,
    state: 'ground',
    home: null,
    homeId: -1,
    phase: rnd() * Math.PI * 2,
    near: false,
    spin: new THREE.Vector3(),
    vel: new THREE.Vector3(),
