/* Tiny WebAudio instrument — every sound is synthesized, no external assets. */
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.muted = false
    this.noiseBuffer = null
    this.ambient = null
    this.birdTimer = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.42
    this.master.connect(this.ctx.destination)
    this.noiseBuffer = this.makeNoise(2)
    this.startAmbience()
  }

  makeNoise(seconds = 1) {
    const ctx = this.ctx
    const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      data[i] = last * 3.2
    }
    return buffer
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.42, this.ctx.currentTime, 0.04)
    return muted
  }

  toggleMute() {
    return this.setMuted(!this.muted)
  }

  startAmbience() {
    const ctx = this.ctx
    if (!ctx) return
    const src = ctx.createBufferSource()
    src.buffer = this.makeNoise(3)
    src.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 420
    const gain = ctx.createGain()
    gain.gain.value = 0.05
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    src.start()
    this.ambient = { src, gain, filter }

    const scheduleBird = () => {
      if (!this.muted && this.ctx) this.bird()
      this.birdTimer = window.setTimeout(scheduleBird, 3200 + Math.random() * 6500)
    }
    this.birdTimer = window.setTimeout(scheduleBird, 2600)
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0
  }

  tone({ freq = 440, freqEnd = null, type = 'sine', dur = 0.15, gain = 0.2, delay = 0, attack = 0.005 }) {
    if (!this.ctx) return
    const t = this.now() + delay
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (freqEnd !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t + dur)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + dur + 0.02)
  }

  noise({ dur = 0.2, gain = 0.2, type = 'lowpass', freq = 900, freqEnd = null, delay = 0, q = 0.8 }) {
    if (!this.ctx || !this.noiseBuffer) return
    const t = this.now() + delay
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.Q.value = q
    filter.frequency.setValueAtTime(freq, t)
    if (freqEnd !== null) filter.frequency.exponentialRampToValueAtTime(Math.max(40, freqEnd), t + dur)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + dur + 0.02)
  }

  pickup() {
    this.tone({ freq: 520, freqEnd: 760, type: 'triangle', dur: 0.11, gain: 0.16 })
    this.tone({ freq: 1040, type: 'sine', dur: 0.08, gain: 0.06, delay: 0.05 })
  }

  deposit() {
    const notes = [392, 523, 659, 784]
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.16, gain: 0.13, delay: i * 0.055 }))
    this.noise({ dur: 0.25, gain: 0.06, type: 'bandpass', freq: 1200, delay: 0.05 })
  }

  throw() {
    this.noise({ dur: 0.28, gain: 0.14, type: 'bandpass', freq: 1900, freqEnd: 380, q: 1.4 })
    this.tone({ freq: 190, freqEnd: 90, type: 'sine', dur: 0.12, gain: 0.08 })
  }

  splat() {
    this.noise({ dur: 0.24, gain: 0.24, type: 'lowpass', freq: 1500, freqEnd: 200, q: 0.6 })
    this.tone({ freq: 120, freqEnd: 55, type: 'sine', dur: 0.18, gain: 0.18 })
  }

  scream() {
    this.tone({ freq: 420, freqEnd: 880, type: 'sawtooth', dur: 0.18, gain: 0.07 })
    this.tone({ freq: 880, freqEnd: 360, type: 'sawtooth', dur: 0.4, gain: 0.06, delay: 0.18 })
    this.tone({ freq: 700, freqEnd: 300, type: 'square', dur: 0.35, gain: 0.025, delay: 0.2 })
  }

  tackle() {
    this.noise({ dur: 0.5, gain: 0.3, type: 'lowpass', freq: 800, freqEnd: 90, q: 0.7 })
    this.tone({ freq: 90, freqEnd: 38, type: 'sine', dur: 0.5, gain: 0.32 })
    this.tone({ freq: 180, freqEnd: 80, type: 'triangle', dur: 0.4, gain: 0.12, delay: 0.04 })
    this.tone({ freq: 1200, freqEnd: 200, type: 'sawtooth', dur: 0.3, gain: 0.04, delay: 0.08 })
  }

  bunny() {
    this.tone({ freq: 900, freqEnd: 1300, type: 'sine', dur: 0.09, gain: 0.11 })
    this.tone({ freq: 1200, freqEnd: 900, type: 'sine', dur: 0.1, gain: 0.08, delay: 0.1 })
    this.tone({ freq: 1500, type: 'sine', dur: 0.06, gain: 0.05, delay: 0.22 })
  }

  batman() {
    this.tone({ freq: 78, freqEnd: 58, type: 'square', dur: 0.5, gain: 0.05 })
    this.tone({ freq: 120, freqEnd: 90, type: 'sawtooth', dur: 0.4, gain: 0.025, delay: 0.05 })
  }

  footstep(run = false) {
    this.noise({ dur: 0.08, gain: run ? 0.055 : 0.035, type: 'lowpass', freq: 260, freqEnd: 90 })
  }

  click() {
    this.tone({ freq: 660, freqEnd: 440, type: 'square', dur: 0.05, gain: 0.03 })
  }

  deny() {
    this.tone({ freq: 210, freqEnd: 150, type: 'square', dur: 0.14, gain: 0.06 })
  }

  bird() {
    const base = 1800 + Math.random() * 1300
    const notes = 2 + Math.floor(Math.random() * 3)
    for (let i = 0; i < notes; i++) {
      this.tone({ freq: base, freqEnd: base * (0.7 + Math.random() * 0.6), type: 'sine', dur: 0.06 + Math.random() * 0.05, gain: 0.017, delay: i * 0.09, attack: 0.004 })
    }
  }

  fanfare() {
    const melody = [523, 659, 784, 1047, 784, 1047, 1319]
    melody.forEach((f, i) => {
      this.tone({ freq: f, type: 'triangle', dur: 0.28, gain: 0.13, delay: i * 0.11 })
      this.tone({ freq: f / 2, type: 'sine', dur: 0.3, gain: 0.08, delay: i * 0.11 })
    })
    this.tone({ freq: 1568, type: 'triangle', dur: 0.8, gain: 0.1, delay: 0.85 })
  }
}

import * as THREE from 'three'
import { makeComicSprite, makeIconTexture } from './utils.js'

export function createEffects(scene, camera, comicLayer) {
  const bursts = []
  const impacts = []
  const shocks = []
  const heartTexture = makeIconTexture('heart')

  function burst(position, color = 0xffcf4a, count = 16, opts = {}) {
    const positions = new Float32Array(count * 3)
    const velocities = new Float32Array(count * 3)
    const colors = opts.colors ? new Float32Array(count * 3) : null
    const colorObj = new THREE.Color()
    for (let i = 0; i < count; i++) {
      positions[i * 3] = position.x + (Math.random() - 0.5) * (opts.spread || 0.2)
      positions[i * 3 + 1] = position.y + (Math.random() - 0.5) * (opts.spread || 0.2)
      positions[i * 3 + 2] = position.z + (Math.random() - 0.5) * (opts.spread || 0.2)
      const speed = (opts.speed || 3) * (0.35 + Math.random() * 0.9)
      const theta = Math.random() * Math.PI * 2
      const phi = Math.random() * Math.PI
      velocities[i * 3] = Math.cos(theta) * Math.sin(phi) * speed
      velocities[i * 3 + 1] = Math.cos(phi) * speed + (opts.up || 1.5)
      velocities[i * 3 + 2] = Math.sin(theta) * Math.sin(phi) * speed
      if (colors) {
        const c = opts.colors[Math.floor(Math.random() * opts.colors.length)]
        colorObj.set(c)
        colors[i * 3] = colorObj.r
        colors[i * 3 + 1] = colorObj.g
        colors[i * 3 + 2] = colorObj.b
      }
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    if (colors) geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    const mat = new THREE.PointsMaterial({
      color: colors ? 0xffffff : color,
      size: opts.size || 0.16,
      transparent: true,
      opacity: 1,
      depthWrite: false,
      vertexColors: Boolean(colors),
      map: opts.texture || null,
      alphaTest: opts.texture ? 0.1 : 0,
      sizeAttenuation: true,
    })
    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false
    scene.add(points)
    bursts.push({
      points,
      velocities,
      life: opts.life || 1.1,
      maxLife: opts.life || 1.1,
      gravity: opts.gravity ?? 9,
      grow: opts.grow ?? 0,
    })
  }

  function hearts(position, count = 10) {
    burst(position, 0xffffff, count, {
      texture: heartTexture,
      size: 0.4,
      speed: 1.1,
      up: 1.9,
      gravity: -0.35,
      life: 1.5,
      spread: 0.4,
    })
  }

  function confetti(position) {
    const colors = [0xffcf4a, 0xff7a3c, 0x3e9d62, 0x8ec5e8, 0xff9ab5, 0xfff7e3]
    for (let i = 0; i < 4; i++) {
      burst(
        { x: position.x + (Math.random() - 0.5) * 3, y: position.y + 2 + Math.random() * 2, z: position.z + (Math.random() - 0.5) * 3 },
        0xffffff,
        22,
        { colors, size: 0.14, speed: 5, up: 6, gravity: 7, life: 2.6, spread: 0.5, grow: 0 }
      )
    }
  }

  function impactText(text, position, color = '#ffcf4a', scale = 1) {
    const sprite = makeComicSprite(text, color, scale)
    sprite.position.copy(position)
    scene.add(sprite)
    impacts.push({ sprite, life: 1.25, maxLife: 1.25, vy: 1.1 })
  }

  function shockwave(position, color = 0xffe27a) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false })
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.7, 0.95, 36), mat)
    ring.rotation.x = -Math.PI / 2
    ring.position.copy(position)
    scene.add(ring)
    shocks.push({ mesh: ring, life: 0.7, maxLife: 0.7 })
  }

  function comicPop(text, position, { color = '#ffcf4a', size = 30, rot = -6 } = {}) {
    const v = position.clone ? position.clone() : new THREE.Vector3(position.x, position.y, position.z)
    v.project(camera)
    if (v.z > 1 || v.z < -1) return
    const x = (v.x * 0.5 + 0.5) * window.innerWidth
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight
    if (x < -80 || x > window.innerWidth + 80 || y < -60 || y > window.innerHeight + 60) return
    const node = document.createElement('div')
    node.className = 'comic-pop'
    node.textContent = text
    node.style.left = `${x}px`
    node.style.top = `${y}px`
    node.style.setProperty('--size', `${size}px`)
    node.style.setProperty('--rot', `${rot}deg`)
    node.style.color = color
    comicLayer.appendChild(node)
    window.setTimeout(() => node.remove(), 1250)
  }

  function dust(position, count = 8) {
    burst(position, 0xc9b98f, count, { size: 0.11, speed: 1.2, up: 0.7, gravity: 1.2, life: 0.65, spread: 0.25 })
  }

  function splat(position) {
    burst(position, 0x7d5b34, 20, { size: 0.14, speed: 2.4, up: 1.7, gravity: 10, life: 0.9, spread: 0.2 })
    burst(position, 0xd8b463, 8, { size: 0.1, speed: 3.2, up: 2.2, gravity: 12, life: 0.7 })
  }

  function stars(position) {
    burst(position, 0xffe27a, 30, { size: 0.22, speed: 4.5, up: 1.5, gravity: 5, life: 1.2, colors: [0xffe27a, 0xffffff, 0xffb52e] })
  }

  function update(dt) {
    for (let i = bursts.length - 1; i >= 0; i--) {
      const b = bursts[i]
      b.life -= dt
      const pos = b.points.geometry.attributes.position.array
      for (let p = 0; p < b.velocities.length / 3; p++) {
        b.velocities[p * 3 + 1] -= b.gravity * dt
        pos[p * 3] += b.velocities[p * 3] * dt
        pos[p * 3 + 1] += b.velocities[p * 3 + 1] * dt
        pos[p * 3 + 2] += b.velocities[p * 3 + 2] * dt
      }
      b.points.geometry.attributes.position.needsUpdate = true
      b.points.material.opacity = Math.max(0, b.life / b.maxLife)
      if (b.grow) {
        const s = 1 + (1 - b.life / b.maxLife) * b.grow
        b.points.scale.setScalar(s)
      }
      if (b.life <= 0) {
        scene.remove(b.points)
        b.points.geometry.dispose()
        b.points.material.map?.dispose?.()
        b.points.material.dispose()
        bursts.splice(i, 1)
      }
    }
    for (let i = impacts.length - 1; i >= 0; i--) {
      const im = impacts[i]
      im.life -= dt
      im.sprite.position.y += im.vy * dt
      im.sprite.material.opacity = Math.max(0, Math.min(1, im.life / (im.maxLife * 0.4)))
      if (im.life <= 0) {
        scene.remove(im.sprite)
        im.sprite.material.map?.dispose?.()
        im.sprite.material.dispose()
        impacts.splice(i, 1)
      }
    }
    for (let i = shocks.length - 1; i >= 0; i--) {
      const s = shocks[i]
      s.life -= dt
      const k = 1 - s.life / s.maxLife
      s.mesh.scale.setScalar(1 + k * 8)
      s.mesh.material.opacity = Math.max(0, 0.9 * (1 - k))
      if (s.life <= 0) {
        scene.remove(s.mesh)
        s.mesh.geometry.dispose()
        s.mesh.material.dispose()
        shocks.splice(i, 1)
      }
    }
  }

  return {
    burst,
    hearts,
    confetti,
    impactText,
    shockwave,
    comicPop,
    dust,
    splat,
    stars,
    update,
  }
}

import * as THREE from 'three'
import { clamp, pick, setSpeech } from './utils.js'
import { updatePersonAnim } from './characters.js'

const MAX_BAG = 10
const BUBBLE_LINES = ['HEY!', 'MEIN HEMD!', 'IGITT!', 'WAS SOLL DAS?!', 'NICHT DIE FRISUR!', 'MAMA!', 'HILFE!']
const COMIC_WORDS = ['PENG!', 'BONK!', 'KLATSCH!', 'WUMM!', 'SPLAT!']
const BATMAN_LINES = ['HMMM!', 'AUTSCH!', 'ICH BIN DIE NACHT!', 'NICHT DIE FLEDERMAUS!', 'WER WAR DAS?!']
const TACKLE_WORDS = ['PENG!', 'WUMM!', 'BONK!']

export function createGameplay({ world, player, camera, hud, effects, audio, onWin }) {
  const state = {
    score: 0,
    bag: 0,
    carrots: 0,
    cleaned: 0,
    housesCleared: 0,
    bonks: 0,
    tackles: 0,
    fed: 0,
    combo: 0,
    comboTimer: 0,
    shake: 0,
    active: false,
    won: false,
    winPending: false,
    winTimer: 0,
    interaction: null,
    firstPickup: false,
    firstHit: false,
    firstTackle: false,
    firstFeed: false,
  }

  const heldTrash = []
  const camDir = new THREE.Vector3()
  const tmpVec = new THREE.Vector3()
  const tmpVec2 = new THREE.Vector3()
  const center = new THREE.Vector3()

  hud.setBag(0, MAX_BAG)
  hud.setCarrots(0)
  hud.setScore(0)
  hud.setProgress(0, 0)

  /* ------------------------------------------------------------
     helpers
     ------------------------------------------------------------ */
  function addScore(points) {
    state.score += points
    hud.setScore(state.score)
  }

  function updateProgress() {
    hud.setProgress(state.cleaned, state.housesCleared)
  }

  function countDeposited() {
    return world.trashItems.reduce((n, item) => n + (item.state === 'deposited' ? 1 : 0), 0)
  }

  function depositItem(item, direct = false, silent = false) {
    if (item.state === 'deposited') return 0
    item.state = 'deposited'
    item.group.visible = false
    item.ring.visible = false
    item.icon.visible = false
    item.near = false
    state.cleaned++
    const points = direct ? 90 : 35
    addScore(points)
    if (!silent) updateProgress()
    checkHouseClear(item.home)
    if (!silent) checkWin()
    return points
  }

  function checkHouseClear(house) {
    if (!house || house.cleared) return false
    if (!house.trash.every((item) => item.state === 'deposited')) return false
    house.cleared = true
    state.housesCleared++
    addScore(250)
    updateProgress()
    const number = 2 + house.id * 2
    hud.banner(`HAUS ${number} IST SAUBER!`, '+250 · Der Nachbar traut sich wieder raus')
    hud.feed(`Haus ${number} komplett geräumt +250`, 'good')
    audio.deposit()
    effects.comicPop('SAUBER!', tmpVec.set(house.x, 3.5, house.z), { color: '#a8efb0', size: 34, rot: 4 })
    return true
  }

  function checkWin() {
    if (state.won || state.winPending) return
    const cleaned = countDeposited()
    if (cleaned < world.totalTrash) return
    state.cleaned = cleaned
    updateProgress()
    state.winPending = true
    state.winTimer = 1.5
    hud.banner('ALLES SAUBER!', 'Die Nachbarschaft glänzt · Auftrag erledigt', 2600)
    hud.feed('Alle Müllteile entsorgt. Wahnsinn.', 'good')
    audio.fanfare()
    effects.confetti(player.pos)
    effects.comicPop('SAUBER!', tmpVec.set(player.pos.x, 2.4, player.pos.z), { color: '#a8efb0', size: 44, rot: -4 })
  }

  function stats() {
    return {
      score: state.score,
      cleaned: state.cleaned,
      bonks: state.bonks,
      tackles: state.tackles,
      fed: state.fed,
      houses: state.housesCleared,
    }
  }

  function isWinLocked() {
    return state.won || state.winPending
  }

  /* ------------------------------------------------------------
     interaction detection
     ------------------------------------------------------------ */
  function playerForward() {
    return tmpVec2.set(-Math.sin(player.yaw), 0, -Math.cos(player.yaw))
  }

  function findInteraction() {
    const forward = playerForward()
    let bestTrash = null
    let bestTrashDist = 3.1
    let bestCarrot = null
    let bestCarrotDist = 2.5

    for (const item of world.trashItems) {
      const isGround = item.state === 'ground'
      const pos = item.group.position
      const dx = pos.x - player.pos.x
      const dz = pos.z - player.pos.z
      const dist = Math.hypot(dx, dz)
      const near = isGround && dist < 3.8
      item.near = near
      item.ring.visible = near && item.collectCool <= 0
      item.icon.visible = near && item.collectCool <= 0
      if (!isGround || item.collectCool > 0) continue
      const dot = dist > 0.01 ? (dx * forward.x + dz * forward.z) / dist : 1
      if (dist < bestTrashDist && (dot > 0.15 || dist < 1.7)) {
        bestTrashDist = dist
        bestTrash = item
      }
    }

    for (const carrot of world.carrots) {
      if (carrot.state !== 'ground') continue
      const pos = carrot.group.position
      const dx = pos.x - player.pos.x
      const dz = pos.z - player.pos.z
      const dist = Math.hypot(dx, dz)
      if (dist < bestCarrotDist) {
        const dot = dist > 0.01 ? (dx * forward.x + dz * forward.z) / dist : 1
        if (dot > 0.05 || dist < 1.5) {
          bestCarrotDist = dist
          bestCarrot = carrot
        }
      }
    }

    const truckDist = Math.hypot(world.depositPoint.x - player.pos.x, world.depositPoint.z - player.pos.z)
    if (truckDist < 3.5 && heldTrash.length > 0) {
      return { type: 'deposit', label: `${heldTrash.length} Müllteile am Laster abladen`, verb: 'Abladen' }
    }

    const bunny = world.bunny
    if (bunny) {
      const bunnyDist = Math.hypot(bunny.group.position.x - player.pos.x, bunny.group.position.z - player.pos.z)
      if (bunnyDist < 2.9 && state.carrots > 0) {
        return { type: 'feed', label: 'Max mit einer Karotte füttern', verb: 'Füttern' }
      }
      if (bunnyDist < 2.9 && state.carrots === 0 && !bestTrash && !bestCarrot) {
        return { type: 'maxHungry', label: 'Max hat Hunger – finde eine Karotte', verb: 'Max' }
      }
    }

    if (bestTrash) {
      if (state.bag >= MAX_BAG) return { type: 'bagfull', item: bestTrash, label: 'Tüte voll – erst am Laster abladen', verb: 'Voll' }
      return { type: 'trash', item: bestTrash, label: `${bestTrash.name} aufheben`, verb: 'Nehmen' }
    }

    if (bestCarrot) {
      return { type: 'carrot', item: bestCarrot, label: 'Karotte aufheben', verb: 'Aufheben' }
    }

    return null
  }

  function refreshInteraction() {
    if (!state.active || isWinLocked()) {
      state.interaction = null
      hud.setPrompt(null)
      hud.setActionLabel('Nehmen')
      return
    }
    const action = findInteraction()
    state.interaction = action
    if (!action) {
      hud.setPrompt(null)
      hud.setActionLabel('Nehmen')
      return
    }
    hud.setPrompt(action.label)
    hud.setActionLabel(action.verb)
  }

  /* ------------------------------------------------------------
     actions
     ------------------------------------------------------------ */
  function interact() {
    if (!state.active || isWinLocked()) return
    const action = state.interaction || findInteraction()
    if (!action) return

    if (action.type === 'deposit') {
      const count = heldTrash.length
      if (!count) {
        hud.toast('Nichts zum Abladen in der Tüte.', 'warn')
        return
      }
      let points = 0
      for (const item of heldTrash.slice()) {
        points += depositItem(item, false)
      }
      heldTrash.length = 0
      state.bag = 0
      hud.setBag(state.bag, MAX_BAG)
      addScore(5 * count)
      points += 5 * count
      audio.deposit()
      hud.toast(`${count} Müllteile entsorgt · +${points}`, 'good', 2400)
      hud.feed(`${count} Müllteile abgeladen +${points}`, 'good')
      effects.burst(tmpVec.set(world.depositPoint.x, 1.4, world.depositPoint.z), 0xa8efb0, 18, { speed: 2.6, up: 2.2, size: 0.15, life: 0.9 })
      refreshInteraction()
      checkWin()
      return
    }

    if (action.type === 'bagfull') {
      audio.deny()
      hud.toast('Tüte voll! Bring den Müll zum Laster.', 'warn')
      return
    }

    if (action.type === 'maxHungry') {
      audio.deny()
      hud.toast('Max will eine Karotte. Such eine im Garten!', 'warn')
      return
    }

    if (action.type === 'trash') {
      const item = action.item
      if (state.bag >= MAX_BAG) {
        audio.deny()
        hud.toast('Tüte voll!', 'warn')
        return
      }
      item.state = 'held'
      item.group.visible = false
      item.ring.visible = false
      item.icon.visible = false
      item.near = false
      heldTrash.push(item)
      state.bag++
      addScore(10)
      hud.setBag(state.bag, MAX_BAG)
      audio.pickup()
      effects.comicPop('+10', tmpVec.copy(item.group.position).setY(0.9), { color: '#fff7e3', size: 19, rot: -4 })
      if (!state.firstPickup) {
        state.firstPickup = true
        hud.toast('Gut! Bring den Müll zum Laster – oder wirf ihn auf Nachbarn.', '', 3600)
        hud.feed('Tipp: Am Müll-Laster hinten alles abladen.', '')
      }
      refreshInteraction()
      return
    }

    if (action.type === 'carrot') {
      const carrot = action.item
      carrot.state = 'held'
      carrot.group.visible = false
      carrot.respawn = 28
      state.carrots++
      addScore(15)
      hud.setCarrots(state.carrots)
      audio.pickup()
      hud.feed('Karotte gefunden · +15', 'good')
      hud.toast('Karotte! Max wird sich freuen.', 'good', 1800)
      effects.burst(tmpVec.copy(carrot.group.position).setY(0.6), 0x9ef28a, 10, { speed: 1.4, up: 1.6, size: 0.1, life: 0.8 })
      refreshInteraction()
      return
    }

    if (action.type === 'feed') {
      const bunny = world.bunny
      if (state.carrots <= 0) {
        hud.toast('Keine Karotte in der Tasche.', 'warn')
        return
      }
      state.carrots--
      state.fed++
      addScore(200)
      hud.setCarrots(state.carrots)
      bunny.follow = 42
      bunny.happy = 5
      bunny.state = 'follow'
      bunny.target.set(player.pos.x, 0, player.pos.z)
      audio.bunny()
      effects.hearts(tmpVec.copy(bunny.group.position).setY(0.9), 12)
      effects.comicPop('MAX ♥', tmpVec.copy(bunny.group.position).setY(1.6), { color: '#ffc2d3', size: 27, rot: -5 })
      hud.toast('Max mag dich. Sehr.', 'good', 2100)
      hud.feed('Max gefüttert +200 · Er hoppelt hinterher', 'good')
      if (!state.firstFeed) {
        state.firstFeed = true
        hud.feed('Max folgt dir jetzt eine Weile. Süß.', 'good')
      }
      refreshInteraction()
    }
  }

  /* ------------------------------------------------------------
     throwing
     ------------------------------------------------------------ */
  function throwTrash(power = 1) {
    if (!state.active || isWinLocked()) return false
    if (heldTrash.length === 0) {
      audio.deny()
      hud.toast('Deine Tüte ist leer! Sammle erst Müll.', 'warn')
      return false
    }
    const item = heldTrash.pop()
    state.bag = Math.max(0, state.bag - 1)
    hud.setBag(state.bag, MAX_BAG)

    camDir.set(0, 0, -1).applyEuler(new THREE.Euler(player.pitch, player.yaw, 0, 'YXZ'))
    const speed = 13 + power * 11
    item.state = 'flying'
    item.group.visible = true
    item.group.position.copy(camera.position).addScaledVector(camDir, 0.65)
    item.group.position.y -= 0.08
    item.group.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
    item.vel.copy(camDir).multiplyScalar(speed)
    item.vel.y += 1.4 + power * 1.4
    item.spin.set((Math.random() - 0.5) * 14, (Math.random() - 0.5) * 14, (Math.random() - 0.5) * 14)
    item.hitNpcs = item.hitNpcs || new Set()
    item.hitNpcs.clear()
    item.hitBatman = false
    item.collectCool = 0
    item.ring.visible = false
    item.icon.visible = false
    audio.throw()
    refreshInteraction()
    return true
  }

  function landItem(item) {
    item.state = 'ground'
    item.vel.set(0, 0, 0)
    item.collectCool = 0.35
    item.group.position.y = 0.02
    item.group.rotation.x = 0
    item.group.rotation.z = 0
    item.group.rotation.y = Math.random() * Math.PI * 2
    resolveLitter(item.group.position)
    effects.dust(tmpVec.copy(item.group.position).setY(0.1), 7)
  }

  function resolveLitter(pos) {
    pos.x = clamp(pos.x, world.bounds.minX + 1, world.bounds.maxX - 1)
    pos.z = clamp(pos.z, world.bounds.minZ + 1, world.bounds.maxZ - 1)
    const r = 0.28
    for (const c of world.colliders) {
      if (pos.x > c.minX - r && pos.x < c.maxX + r && pos.z > c.minZ - r && pos.z < c.maxZ + r) {
        const dx1 = pos.x - (c.minX - r)
        const dx2 = c.maxX + r - pos.x
        const dz1 = pos.z - (c.minZ - r)
        const dz2 = c.maxZ + r - pos.z
        const min = Math.min(dx1, dx2, dz1, dz2)
        if (min === dx1) pos.x = c.minX - r
        else if (min === dx2) pos.x = c.maxX + r
        else if (min === dz1) pos.z = c.minZ - r
        else pos.z = c.maxZ + r
      }
    }
  }

  function hitNPC(item, npc, point) {
    item.hitNpcs.add(npc.id)
    npc.state = 'flee'
    npc.stateT = 1.05
    npc.fleeX = npc.group.position.x - player.pos.x
    npc.fleeZ = npc.group.position.z - player.pos.z
    const len = Math.hypot(npc.fleeX, npc.fleeZ) || 1
    npc.fleeX /= len
    npc.fleeZ /= len
    npc.bubbleT = 1.9
    setSpeech(npc.speech, pick(BUBBLE_LINES), '#b23a2e')
    npc.speech.scale.set(2.1, 0.72, 1)

    state.combo = state.comboTimer > 0 ? state.combo + 1 : 1
    state.comboTimer = 4.6
    const multiplier = Math.min(5, state.combo)
    const points = 150 * multiplier
    state.bonks++
    addScore(points)
    audio.splat()
    audio.scream()
    effects.splat(point)
    effects.comicPop(`${pick(COMIC_WORDS)} +${points}`, tmpVec.copy(point).add(tmpVec2.set(0, 0.5, 0)), { color: '#ffcf4a', size: 28, rot: -5 })
    if (multiplier > 1) effects.comicPop(`x${multiplier}`, tmpVec.copy(point).add(tmpVec2.set(0, 1.1, 0)), { color: '#ff9ab5', size: 22, rot: 7 })
    hud.feed(`Nachbar getroffen +${points}${multiplier > 1 ? ` · x${multiplier}` : ''}`, 'hot')

    item.vel.multiplyScalar(0.34)
    item.vel.y = 2.2
    item.spin.set((Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9)

    if (!state.firstHit) {
      state.firstHit = true
      hud.toast('Er rennt weg … und fliegt gleich zu Batman!', '', 3800)
      hud.feed('Tipp: Getroffene Nachbarn fliegen zu Batman und tacklen ihn.', '')
    }
    refreshInteraction()
  }

  function hitBatman(item, point) {
    item.hitBatman = true
    addScore(120)
    const batman = world.batman
    batman.hitFlash = 1
    batman.stun = Math.max(batman.stun, 1.15)
    batman.bubbleT = 2.2
    setSpeech(batman.speech, pick(BATMAN_LINES), '#b23a2e')
    audio.batman()
    audio.splat()
    effects.splat(point)
    effects.comicPop('BATMAN BESCHMUTZT +120', tmpVec.copy(point).setY(point.y + 1.4), { color: '#c9d7ff', size: 24, rot: 3 })
    hud.feed('Batman direkt getroffen +120', 'hot')
    item.vel.multiplyScalar(0.3)
    item.vel.y = 1.8
  }

  function tackleBatman(npc) {
    const batman = world.batman
    npc.state = 'gone'
    npc.group.visible = false
    npc.speech.visible = false
    npc.respawnT = 6 + Math.random() * 7
    state.tackles++
    addScore(500)
    state.shake = 0.55
    batman.stun = 2.7
    batman.hitFlash = 1
    batman.bubbleT = 2.8
    setSpeech(batman.speech, pick(BATMAN_LINES), '#b23a2e')
    audio.tackle()
    audio.batman()

    const bp = batman.group.position.clone()
    bp.y += 2.3
    effects.stars(bp)
    effects.shockwave(bp)
    effects.impactText(pick(TACKLE_WORDS), bp.clone().add(tmpVec.set(0, 0.8, 0)), '#ffcf4a', 1.4)
    effects.comicPop('BATMAN-TACKLE! +500', bp.clone().add(tmpVec.set(0, 0.2, 0)), { color: '#ffcf4a', size: 40, rot: -3 })
    hud.feed('Batman-Tackle +500 · Die Nachbarschaft wehrt sich', 'good')
    if (!state.firstTackle) {
      state.firstTackle = true
      hud.banner('BATMAN-TACKLE!', '+500 · Ein fliegender Nachbar, ein müder Batman')
    } else {
      hud.toast('Batman-Tackle! +500', 'good', 1800)
    }
    refreshInteraction()
  }

  /* marker: update-functions */
  return null
}

