{
  "name": "muellmann",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "MÜLLMANN – a comic first-person neighborhood cleanup game built with Three.js",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
