const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--use-gl=angle','--use-angle=swiftshader','--no-sandbox'] })
const page = await browser.newPage({ viewport: { width: 1200, height: 750 } })
