  const c=__game.world.carrots[0]
  const p=c.group.position
  const px=p.x-0.1, pz=p.z+1.45
  const yaw=Math.atan2(-(p.x-px), -(p.z-pz))
  __game.teleport(px,pz,yaw); __game.look(yaw,-0.35)
  const f={x:-Math.sin(yaw),z:-Math.cos(yaw)}
  const out=[]
  for (const carrot of __game.world.carrots) {
    if (carrot.state!=='ground') continue
    const pos=carrot.group.position
    const dx=pos.x-__game.player.pos.x,dz=pos.z-__game.player.pos.z
    const d=Math.hypot(dx,dz); const dot=d>0.01?(dx*f.x+dz*f.z)/d:1
    if (d<4) out.push({kind:'carrot',d,dot,score:d-dot*0.9, state:carrot.state})
  }
  for (const item of __game.world.trashItems) {
    if (item.state!=='ground') continue
    const pos=item.group.position
    const dx=pos.x-__game.player.pos.x,dz=pos.z-__game.player.pos.z
    const d=Math.hypot(dx,dz); const dot=d>0.01?(dx*f.x+dz*f.z)/d:1
    if (d<4) out.push({kind:'trash',name:item.name,d,dot,score:d-dot*0.9,state:item.state,cool:item.collectCool})
  }
  return {yaw, f, carrots:__game.world.carrots.length, out}
}))
await browser.close()

